/**
 * Copies the site's generated Drizzle schema into `community-agent/`.
 *
 * The agent needs the same table definitions as the Next.js app, but it is a
 * separate npm package and eve's dev bundler refuses to resolve imports that
 * escape the agent root (`eve build` allows it, `eve dev` does not — so a
 * cross-package relative import breaks the daily workflow while still building).
 *
 * Copying rather than hand-maintaining a second schema keeps
 * `src/db/site/schema.ts` — itself generated by `drizzle-kit pull` — the single
 * source of truth. This script runs from the root `predev`, `prebuild`, and
 * `postinstall`, so the copy is refreshed before anything can read a stale one.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = resolve(root, "src/db/site/schema.ts");
const target = resolve(root, "community-agent/agent/lib/site-schema.ts");

const header = `// GENERATED FILE — DO NOT EDIT.
//
// Copied from src/db/site/schema.ts by scripts/sync-agent-schema.mjs, which runs
// on predev, prebuild and postinstall. Edit the source file instead; anything
// written here is overwritten on the next build.

`;

const contents = readFileSync(source, "utf8");
const next = header + contents;

// Only write when the content actually changes, so watchers don't see a touched
// file on every single dev boot.
let current = "";
try {
  current = readFileSync(target, "utf8");
} catch {
  // First run: the file does not exist yet.
}

if (current !== next) {
  writeFileSync(target, next);
  console.log("[sync-agent-schema] updated community-agent/agent/lib/site-schema.ts");
}
